class Solution {
    public boolean canPartition(int[] nums) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % 2 != 0) return false;
        return f(nums, 0, total / 2);
    }

    private boolean f(int[] nums, int i, int rest) {
        if (rest == 0) return true;
        if (i == nums.length || rest < 0) return false;
        return f(nums, i + 1, rest) || f(nums, i + 1, rest - nums[i]);
    }
}

class Solution {
    public boolean canPartition(int[] nums) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % 2 != 0) return false;

        int target = total / 2;
        int n = nums.length;
        boolean[][] dp = new boolean[n + 1][target + 1];
        for (int i = 0; i <= n; i++) dp[i][0] = true;

        for (int i = 1; i <= n; i++) {
            int v = nums[i - 1];
            for (int j = 1; j <= target; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j >= v && dp[i - 1][j - v]) dp[i][j] = true;
            }
        }
        return dp[n][target];
    }
}

class Solution {
    public boolean canPartition(int[] nums) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % 2 != 0) return false;

        int target = total / 2;
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;

        for (int v : nums) {
            for (int j = target; j >= v; j--) {
                if (dp[j - v]) dp[j] = true;
            }
            if (dp[target]) return true;
        }
        return dp[target];
    }
}
